function cookie(e){let t=e=>document.cookie=e;function n(){let t=decodeURIComponent(document.cookie).split(";");for(let n=0;n<t.length;n++){let o=t[n].trim().split("=");if(o[0]===e)return o.slice(1).join("=")}}function o(n,o=null){const i=e+"="+n+";path=/";if(null===o)t(i);else{const e=new Date;e.setTime(e.getTime()+1e3*o),t(i+";expires="+e.toUTCString())}}return{value:n,set:o,delete:()=>o("",0),toString:n}}